/**
 * @file monitoring/auto-schedulers.js
 * @description P1-11: 自动定时新闻 (Auto News) 与大V增量画像 (Auto Persona) 调度器
 *
 * 迁移自 server.js，供 ingest_runner.js 独占调用:
 * 1. checkAndAutoGenerateDailyNews: 在工作日的指定交易时点预生成标准的资讯报告，补齐缺失报告
 * 2. checkAndAutoUpdatePersonaPlaybook: 每周日凌晨 03:00 自动触发一次大V增量画像白皮书更新
 */

import { getDb } from '../database.js';

export function getBeijingTodayStartTimestamp(now = new Date()) {
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const hktDate = new Date(utc + (3600000 * 8));
  hktDate.setHours(0, 0, 0, 0);
  const localOffsetMs = now.getTimezoneOffset() * 60000;
  return hktDate.getTime() - (3600000 * 8) - localOffsetMs;
}

/**
 * 自动检测并在工作日的指定交易时点预生成标准的资讯报告
 */
export async function checkAndAutoGenerateDailyNews({ dbInstance = null, generateNewsFn = null } = {}) {
  try {
    const now = new Date();
    const shanghaiFormatter = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Shanghai',
      hourCycle: 'h23',
      weekday: 'short',
      hour: 'numeric',
      minute: 'numeric'
    });

    const parts = {};
    for (const p of shanghaiFormatter.formatToParts(now)) {
      parts[p.type] = p.value;
    }

    const currentHour = (parseInt(parts.hour, 10) || 0) % 24;
    const currentMinute = parseInt(parts.minute, 10) || 0;

    const todayStartMs = getBeijingTodayStartTimestamp(now);
    const db = dbInstance || getDb();

    // 扫描最近 2 天（今天与昨天）
    for (let dayOffset = 0; dayOffset < 2; dayOffset++) {
      const targetDayMs = todayStartMs - (dayOffset * 24 * 60 * 60 * 1000);
      const targetDate = new Date(targetDayMs);
      const targetDayOfWeek = targetDate.getDay();
      const d = targetDayOfWeek === 0 ? 7 : targetDayOfWeek;

      const configs = [];

      // a. 盘前速报 (briefing) - 仅限周一到周五
      if (d >= 1 && d <= 5) {
        configs.push({
          type: 'briefing',
          triggerHour: 17,
          triggerMinute: 30,
          startTime: targetDayMs + (1.5 * 3600 * 1000),
          endTime: targetDayMs + (17.5 * 3600 * 1000),
        });
      }

      // b. 盘中总结 (intraday) - 仅限周二到周六
      if (d >= 2 && d <= 6) {
        configs.push({
          type: 'intraday',
          triggerHour: 1,
          triggerMinute: 30,
          startTime: targetDayMs + (21.5 * 3600 * 1000),
          endTime: targetDayMs + (25.5 * 3600 * 1000),
        });
      }

      // c. 收盘回顾 (closing) - 仅限周二到周六
      if (d >= 2 && d <= 6) {
        configs.push({
          type: 'closing',
          triggerHour: 8,
          triggerMinute: 30,
          startTime: targetDayMs + (22.5 * 3600 * 1000),
          endTime: targetDayMs + (32.5 * 3600 * 1000),
        });
      }

      for (const config of configs) {
        const { type, triggerHour, triggerMinute, startTime, endTime } = config;

        if (dayOffset === 0) {
          if (currentHour < triggerHour || (currentHour === triggerHour && currentMinute < triggerMinute)) {
            continue; // 时间未到
          }
        }

        const customStartStr = new Date(startTime).toISOString();
        const customEndStr = new Date(endTime).toISOString();

        // 1. 查已生成成功的总结
        const summary = db.prepare(`
          SELECT id FROM news_summaries
          WHERE summary_type = ? AND start_time = ? AND end_time = ?
          LIMIT 1
        `).get(type, startTime, endTime);

        if (summary) continue;

        // 2. 查排队中或运行中的任务
        const activeTask = db.prepare(`
          SELECT id FROM task_queue
          WHERE task_type = 'news_reduce'
            AND status IN ('pending', 'running', 'retry')
            AND json_extract(payload, '$.summaryType') = ?
            AND json_extract(payload, '$.customStartTime') = ?
          LIMIT 1
        `).get(type, customStartStr);

        if (activeTask) continue;

        console.log(`[Auto News Scheduler] Auto-generating missing ${type} summary for dayIndex ${d}`);

        const genNews = generateNewsFn || (await import('../news-engine.js')).generateNewsSummary;
        await genNews(type, {
          customStartTime: customStartStr,
          customEndTime: customEndStr,
          forceRefresh: true
        }).catch(err => {
          if (err.message && err.message.includes('没有任何聊天数据')) {
            console.log(`[Auto News Scheduler] ${type} auto-summary skipped: ${err.message}`);
          } else {
            console.error(`[Auto News Scheduler] Failed to trigger ${type} auto-summary:`, err.message);
          }
        });
      }
    }
  } catch (err) {
    console.error('[Auto News Scheduler] Error checking news automatic generation:', err.message);
  }
}

/**
 * 自动在每周日凌晨 03:00 左右触发一次大V增量画像白皮书更新任务
 */
export async function checkAndAutoUpdatePersonaPlaybook({ dbInstance = null, generatePersonaFn = null } = {}) {
  try {
    const now = new Date();
    const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
    const hktDate = new Date(utc + (3600000 * 8));

    const weekday = hktDate.getDay();
    const currentHour = hktDate.getHours();
    const currentMinute = hktDate.getMinutes();

    // 仅限周日凌晨 03:00 到 03:30 之间尝试触发
    if (weekday === 0 && currentHour === 3 && currentMinute < 30) {
      const db = dbInstance || getDb();

      const latestPlaybook = db.prepare(`
        SELECT created_at FROM reports
        WHERE strategy = 'PERSONA_PLAYBOOK'
        ORDER BY id DESC LIMIT 1
      `).get();

      const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;
      if (latestPlaybook && (Date.now() - latestPlaybook.created_at < THREE_DAYS_MS)) {
        return;
      }

      const activeTask = db.prepare(`
        SELECT id FROM task_queue
        WHERE task_type IN ('persona_map', 'persona_community', 'persona_reduce')
          AND status IN ('pending', 'running', 'retry')
        LIMIT 1
      `).get();

      if (activeTask) return;

      console.log(`[Auto Persona Scheduler] 开始执行周日凌晨大V画像白皮书增量更新任务...`);
      const genPersona = generatePersonaFn || (await import('../persona-engine.js')).generatePersonaPlaybook;
      genPersona({
        provider: process.env.AI_PROVIDER || 'lm-studio',
        maxMonths: 6,
        forceRefresh: false
      }).catch(err => {
        console.error(`[Auto Persona Scheduler] 触发增量画像生成失败:`, err.message);
      });
    }
  } catch (err) {
    console.error(`[Auto Persona Scheduler] 定时检测画像更新异常:`, err.message);
  }
}

/**
 * Ingest 进程每轮 poll tick 成功后调用的聚合调度函数
 */
export async function runPeriodicAutoSchedulers(opts = {}) {
  await checkAndAutoGenerateDailyNews(opts);
  await checkAndAutoUpdatePersonaPlaybook(opts);
}
